INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "お！\nあそこに困ってそうな人発見！", 0, 0, 0, 1, 0, 0, 1.4, 1001, "春咲 ひより", 1, "ヒヨリでっす♪\n元気いっぱいがんばるよ♪", "ねぇねぇ、騎士クン\n手伝ってあげようよ～");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "大切な人を\n守れるようになりたい…って", 0, 0, 0, 1, 0, 0, 1.4, 1002, "草野 優衣", 1, "みんなみたいに\nわたしも強くならなきゃ", "わ、わたし、\nなに言ってるんだろ\nあはは…");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "キミに必要な集中力と感性が", 0, 0, 0, 1, 0, 0, 1.4, 1003, "士条 怜", 1, "フェンシングを始めてみては？", "少しは磨かれると思いますよ。");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "今日はなにして遊ぶ？", 0, 0, 0, 1, 0, 0, 1.5, 1004, "穂高 みそぎ", 1, "ねぇ、にいちゃん！", "みそぎはねぇ、\nかくれんぼやりたい！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "ねぇ…", 0, 0, 0, 1, 0, 0, 1.4, 1006, "風宮 あかり", 1, "風宮あかりです", "私といっしょに…\nいかない？");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "プリンたべたいのー", 0, 0, 0, 1, 0, 0, 1.5, 1007, "出雲 宮子", 1, "出雲宮子なのー", "食べ物の恨みは怖いのー");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "キミもボクの美貌に\n吸い寄せられたんだね。", 0, 0, 0, 1, 0, 0, 1.4, 1008, "虹村 雪", 1, "ボクは虹村雪。", "いいよ。\n見られることは運命さ…");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "我が真名は\nアンネローゼ・フォン・シュテッヒパルム！", 0, 0, 0, 1, 0, 0, 1.4, 1009, "柊杏奈", 1, "フッ…聞いて後悔するがいい！", "人呼んで「疾風の冥姫」!!");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "うさぎさん、\n運命の王子はんに巡りあわせてくれて", 0, 0, 0, 1, 0, 0, 1.5, 1010, "姫宮 真歩", 1, "マホマホ王国のプリンセス、\nまほ姫どす", "ほんまおおきにやわ～♪");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "生き別れたお兄ちゃんを探して\n三千世界！", 0, 0, 0, 1, 0, 0, 1.4, 1011, "衣之咲 璃乃", 1, "衣之咲璃乃です！", "ここで会ったが\n100年目～！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "ち、超能力って…\n何のことかな～？", 0, 0, 0, 1, 0, 0, 1.4, 1012, "柏崎 初音", 1, "私はハツネ、\n結構強いんだよ。\nきらーん☆", "…って、お願い！\n誰にも言わないでおいて～！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "一応カリスマ読モJKやってまっす！", 0, 0, 0, 1, 0, 0, 1.4, 1016, "美波 鈴奈", 1, "ちょす！\n美波鈴奈だよ～♪", "ヒデサイまぢ\nGF（グッドフィーリング）～♪");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "東京は遊園地みたいなところさー", 0, 0, 0, 1, 0, 0, 1.4, 1017, "喜屋武 香織", 1, "はいたーい。\n喜屋武香織さー。", "でも、沖縄もとってもいいとこさー");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "先生って呼ばれるのは\nくすぐったいから", 0, 0, 0, 1, 0, 0, 1.4, 1018, "支倉 伊緒", 1, "支倉伊緒です。", "イオちゃんって呼んでね。");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "あ！/\お兄ちゃ～ん\nまってよ～", 0, 0, 0, 1, 0, 0, 1.5, 1020, "茜 ミミ", 1, "ふえ…？\nミミ、むずかしいこと\nよくわかんない…", "ミミをおいてかないでぇ～");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "あの……\nふぇ……", 0, 0, 0, 1, 0, 0, 1.5, 1021, "栗林 くるみ", 1, "あ…あの…えっと…\n栗…林…くるみ…です……", "ふぇぇぇぇぇん……");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "こんな私に貴重な時間を\n割いていただき、", 0, 0, 0, 1, 0, 0, 1.4, 1022, "風宮 より", 1, "風宮よりです。\nあああああ！", "なんてありがとうございます！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "おにいちゃんどこいくの？\nえ？", 0, 0, 0, 1, 0, 0, 1.5, 1023, "北条 綾音", 1, "私、アヤネ！\nぷうきちと一緒についてってあげるね！", "私こっち行きたいー\nね、早く早くー");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "ふ、不束者ですが\nどうぞ末永く…って、", 0, 0, 0, 1, 0, 0, 1.4, 1025, "天野 すずめ", 1, "わっ…わっ…私、\n天野すずめといいます！", "これて何か違う…\nあああすみません！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "あなたは…運命の……\n伴侶……", 0, 0, 0, 1, 0, 0, 1.4, 1027, "倉石 恵理子", 1, "……クスクス…私は\n…倉石恵理子……", "離しませんわ………\n絶対に…!!");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "その無駄を省くことができれば、\nもっと余裕のある暮らしができるっ！", 0, 0, 0, 1, 0, 0, 1.4, 1028, "佐々木 咲恋", 1, "佐々木咲恋よ。\nねえ、世の中に無駄なことが\n多すぎると思わない？", "…そうでしょ？？");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "ぇっと…\nキミ、私のこと知らないの?!", 0, 0, 0, 1, 0, 0, 1.4, 1029, "桜井 望", 1, "桜井望だよ！\nよろしくねっ", "あはは、\n私もまだまだだなぁ～");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "初めまして、\n私はニノン・ジュベール申すデス！", 0, 0, 0, 1, 0, 0, 1.4, 1030, "ニノン・ジュベール", 1, "デケデケデンっ！", "ショーグン、\nワタシと一緒に天下統一デース！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "でもって私の隣にいるのが……\nえ、見えない？", 0, 0, 0, 1, 0, 0, 1.4, 1031, "上喜 しのぶ", 1, "上喜しのぶです。\n手元のドクロが父です。", "おかしいですね……");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "けんども\nそれには足りないモンが…", 0, 0, 0, 1, 0, 0, 1.5, 1033, "野戸まひる", 1, "目指すはビッグな\nお笑い芸人だっぺ！", "そう、\nオラのボケに突っ込める相方が…！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "ちょっと緊張しちゃって…", 0, 0, 0, 1, 0, 0, 1.4, 1034, "綾瀬 ゆかり", 1, "あの…私…綾瀬ゆかりです…\nあの…ごめんなさい！", "ちょ\nちょっと一杯飲んできます…！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "知らない人とは話しちゃいけないので", 0, 0, 0, 1, 0, 0, 1.5, 1036, "氷川 鏡華", 1, "氷川鏡華…です", "これ以上お話しすることは…\nないです！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "……あ、アラーム。", 0, 0, 0, 1, 0, 0, 1.4, 1038, "柏崎 栞", 1, "柏崎…栞です。", "私体が弱いから、\n30分に一度休憩しないと\nいけないんです。");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "私、一人も友達がいなくて……", 0, 0, 0, 1, 0, 0, 1.4, 1040, "双葉 碧", 1, "ふ、双葉碧です。", "野に咲く花が、\n唯一の話相手です。");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "私の歌声で、\n皆さんが幸せになってくれたらいいなって…", 0, 0, 0, 1, 0, 0, 1.4, 1042, "三角 千歌", 1, "三角千歌です。", "そう思っています。");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "あぁ？\nお前のそいつの仲間か？", 0, 0, 0, 1, 0, 0, 1.4, 1043, "安芸 真琴", 1, "安芸真琴だ。", "う、疑ってすまなかったな…");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "生けとし生ける全ての者よ！", 0, 0, 0, 1, 0, 0, 1.4, 1044, "イリヤ・オーンスタイン", 1, "わらわこそは夜を総べる者！", "わらわの偉大な力に\nひれ伏すがいい！\nはっはっは！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "ぐふふふふ……はっ！", 0, 0, 0, 1, 0, 0, 1.4, 1045, "遠見 空花", 1, "そこで騎士は妖精を乱暴に……", "ｌク、クウカに何かご用ですか!?");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "自由気ままで♪\n寝て遊んで、食べてケンカして…", 0, 0, 0, 1, 0, 0, 1.4, 1046, "宮坂たまき", 1, "宮坂たまきにゃ♪\n猫はいいにゃよ？", "う～ん…\n猫ってホントに最高にゃ～♪");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "それでは早速クエストに…", 0, 0, 0, 1, 0, 0, 1.4, 1048, "大神 美冬", 1, "大神美冬よ！", "…と思ったら\nバイトの時間だ！\nまたあとでね！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "クエストもバトルも\n掃除も洗濯も", 0, 0, 0, 1, 0, 0, 1.4, 1049, "星野静流", 1, "星野静流だよ！", "お姉ちゃんがぜ～んぶ\nやってあげるからね！");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "見ての通りの\nセクシー美少女で", 0, 0, 0, 1, 0, 0, 1.5, 1050, "玉泉美咲", 1, "アタシは玉泉美咲。", "学校では誰もが憧れる\nアイドル的な存在ってやつよ♪");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "？？？？", 0, 0, 0, 1, 0, 0, 1.4, 1052, "リマ", 1, "？？？", "？？？？");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "菓子でつろうなどと\n稚拙な策を……", 0, 0, 0, 1, 0, 0, 1.5, 1053, "モニカ・ヴァイスヴィント", 1, "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "菓子でつろうなどと\n稚拙な策を……", 0, 0, 0, 1, 0, 0, 1.5, 1058, "ペコリーヌ", 1, "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "菓子でつろうなどと\n稚拙な策を……", 0, 0, 0, 1, 0, 0, 1.5, 1059, "コッコロ", 1, "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる");
INSERT INTO `v1_fc4705949e530fc7de5f13d090377f58e974650d6fe28ffe645610437826e6e2` VALUES (1, 2, "菓子でつろうなどと\n稚拙な策を……", 0, 0, 0, 1, 0, 0, 1.5, 1060, "キャル", 1, "モニカ・ヴァイスヴィントだ。", "そ、そこまでいうなら\nもらってやる");
